def solve_beam_game_v4(grid):
    """
    Each source extends in ALL 4 cardinal directions regardless of edge position.
    Beam length = source value (counting source cell itself).
    """
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    sources = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                sources.append((r, c, grid[r][c]))

    for sr, sc, sv in sources:
        # RIGHT
        c, r = sc + 1, sr
        for _ in range(sv - 1):  # sv-1 additional cells beyond source
            if 0 <= r < h and 0 <= c < w and result[r][c] == 0:
                result[r][c] = sv
                c += 1
            else:
                break

        # LEFT
        c, r = sc - 1, sr
        for _ in range(sv - 1):
            if 0 <= r < h and 0 <= c < w and result[r][c] == 0:
                result[r][c] = sv
                c -= 1
            else:
                break

        # DOWN
        r, c = sr + 1, sc
        for _ in range(sv - 1):
            if 0 <= r < h and 0 <= c < w and result[r][c] == 0:
                result[r][c] = sv
                r += 1
            else:
                break

        # UP
        r, c = sr - 1, sc
        for _ in range(sv - 1):
            if 0 <= r < h and 0 <= c < w and result[r][c] == 0:
                result[r][c] = sv
                r -= 1
            else:
                break

    return result

