def solve_vbeam(grid):
    """
    Rule: 
    1. Vertical beams from row 0 fill entire column with source value
    2. Horizontal beams from edges fill towards opposite edge, stopping at vertical beam columns
    """
    h, w = len(grid), len(grid[0])
    result = [[0]*w for _ in range(h)]

    # Apply vertical beams from row 0
    vert_cols = sorted([c for c in range(w) if grid[0][c] != 0])
    for c in vert_cols:
        sv = grid[0][c]
        for r in range(h):
            result[r][c] = sv

    # Apply horizontal beams
    RIGHT_sources = [(r, c) for r in range(h) for c in range(w) if grid[r][0] != 0]
    LEFT_sources = [(r, c) for r in range(h) for c in range(w) if grid[r][w-1] != 0]

    for r, c in RIGHT_sources:
        sv = grid[r][0]
        # Fill from col 0 towards right, stopping at first vertical col
        for cc in range(w):
            if cc < vert_cols[0]:
                if result[r][cc] == 0:
                    result[r][cc] = sv
            elif cc == vert_cols[0] and result[r][cc] != sv:
                # Stop at this vertical - mismatch
                break

    for r, c in LEFT_sources:
        sv = grid[r][w-1]
        # Fill from col w-1 towards left, filling only after last vertical col
        for cc in range(w-1, -1, -1):
            if cc > vert_cols[-1]:
                if result[r][cc] == 0:
                    result[r][cc] = sv
            elif cc == vert_cols[-1] and result[r][cc] != sv:
                break

    return result

